import{_ as t,o as a,a as n,a2 as i}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Digging Deeper","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/introduction.md","filePath":"advanced/introduction.md","lastUpdated":1789319767000}'),o={name:"advanced/introduction.md"};function s(r,e,h,l,d,c){return a(),n("div",null,e[0]||(e[0]=[i('<h1 id="digging-deeper" tabindex="-1">Digging Deeper <a class="header-anchor" href="#digging-deeper" aria-label="Permalink to &quot;Digging Deeper&quot;">​</a></h1><p>Welcome to the &quot;Digging Deeper&quot; section of Bagisto documentation! This advanced section covers the machinery under the packages, themes and payment or shipping methods you have already built: the core helpers, the indexers, the event system, the console, the queue, the caches and the test suite.</p><div class="info custom-block"><p class="custom-block-title">Prerequisites</p><p>This section assumes you have:</p><ul><li>Completed the <a href="./../package-development/getting-started.html">Package Development</a> guides</li><li>Understanding of <a href="./../theme-development/getting-started.html">Theme Development</a> concepts</li><li>Solid knowledge of Laravel concepts (events, queues, service providers)</li><li>Experience with PHP and object-oriented programming</li></ul></div><h2 id="what-s-in-this-section" tabindex="-1">What&#39;s in this section <a class="header-anchor" href="#what-s-in-this-section" aria-label="Permalink to &quot;What&#39;s in this section&quot;">​</a></h2><h3 id="the-core-and-its-data" tabindex="-1">The core and its data <a class="header-anchor" href="#the-core-and-its-data" aria-label="Permalink to &quot;The core and its data&quot;">​</a></h3><ul><li><strong><a href="./understanding-core-class.html">Understanding Core Class</a></strong>: the <code>core()</code> helper, channels, locales, currencies, configuration, price formatting and the other global helpers.</li><li><strong><a href="./understanding-indexers.html">Understanding Indexers</a></strong>: how price, inventory, flat and search indexes are built and refreshed, and when to run them.</li><li><strong><a href="./understanding-data-transfer.html">Understanding Data Transfer</a></strong>: the queued import pipeline and how to write an importer for your own entity.</li><li><strong><a href="./database-compatibility.html">Database Compatibility</a></strong>: writing queries that run on MySQL, MariaDB and PostgreSQL with <code>db_grammar()</code>.</li><li><strong><a href="./search-engines.html">Search Engines</a></strong>: the database and Elasticsearch engines, the contracts behind them, and how a package adds one.</li><li><strong><a href="./file-storage.html">File Storage</a></strong>: the public disk, S3 and Cloudflare R2, and what switching between them does and does not move.</li></ul><h3 id="hooking-into-the-core" tabindex="-1">Hooking into the core <a class="header-anchor" href="#hooking-into-the-core" aria-label="Permalink to &quot;Hooking into the core&quot;">​</a></h3><ul><li><strong><a href="./event-listeners.html">Event Listeners</a></strong>: the events the core dispatches and how to listen to them.</li><li><strong><a href="./view-render-events.html">View Render Events</a></strong>: injecting markup into existing pages without overriding views.</li><li><strong><a href="./command-palette.html">Command Palette</a></strong>: registering pages, actions and record searches in the admin&#39;s Ctrl+K palette.</li></ul><h3 id="operating-the-application" tabindex="-1">Operating the application <a class="header-anchor" href="#operating-the-application" aria-label="Permalink to &quot;Operating the application&quot;">​</a></h3><ul><li><strong><a href="./artisan-commands.html">Artisan Commands</a></strong>: every <code>bagisto:*</code>, <code>indexer:*</code> and scheduled command.</li><li><strong><a href="./queue-jobs-scheduling.html">Queue, Jobs &amp; Scheduling</a></strong>: what runs on the queue and the scheduler, and how to run workers.</li><li><strong><a href="./cache-strategy.html">Cache Strategy</a></strong>: the caches Bagisto keeps, what invalidates them, and the environment keys that move them to Redis.</li><li><strong><a href="./testing.html">Testing Workflow</a></strong>: the Pest suites, shared datasets and test benches, and the Playwright projects.</li><li><strong><a href="./debugging.html">Debugging Tips</a></strong> and <strong><a href="./common-pitfalls.html">Common Pitfalls</a></strong>: the problems that come up most and how to get out of them.</li></ul><h2 id="why-these-techniques-matter" tabindex="-1">Why These Techniques Matter <a class="header-anchor" href="#why-these-techniques-matter" aria-label="Permalink to &quot;Why These Techniques Matter&quot;">​</a></h2><p>Unlike basic package development, these techniques let you:</p><ul><li><strong>Maintain Upgradability</strong>: extend functionality through events, contracts and configuration rather than by editing core files</li><li><strong>Build Production-Ready Solutions</strong>: run the queue, the scheduler and the caches the way the core expects</li><li><strong>Ship on any database and any storage</strong>: keep a package portable across the engines and disks Bagisto supports</li><li><strong>Handle Complex Business Logic</strong>: solve sophisticated e-commerce requirements</li></ul><h2 id="learning-path" tabindex="-1">Learning Path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning Path&quot;">​</a></h2><p>We recommend following this progression:</p><ol><li><strong>Start with the core class</strong>: most helpers you will call from anywhere are on it</li><li><strong>Then events</strong>: understanding Bagisto&#39;s event system is foundational for the rest</li><li><strong>Then the operational pages</strong>: commands, queue and cache explain what happens after a request ends</li><li><strong>Then the specialised topics</strong>: indexers, search, storage and the command palette as your package needs them</li><li><strong>Finish with testing</strong>: a package without a test suite is one CI run away from breaking</li></ol><div class="tip custom-block"><p class="custom-block-title">Integration with Previous Learning</p><p>These advanced techniques build upon concepts from:</p><ul><li><a href="./../package-development/getting-started.html">Package Development</a> - Service providers, routing, and views</li><li><a href="./../theme-development/getting-started.html">Theme Development</a> - Blade templates and asset management</li><li><a href="./../performance/introduction.html">Performance Optimization</a> - Efficient coding practices</li></ul></div>',17)]))}const p=t(o,[["render",s]]);export{m as __pageData,p as default};
